function solve(args) {
  const s = args[0];
  const n = s.length;
  // We want to find indices i<j<k<l with s[i]=='[' s[j]=='[' s[k]==']' s[l]==']'
  // so that the subsequence s[i], s[j], s[k], s[l] forms "[[]]"
  // i<j<k<l ensures nesting: the inner pair [j,k] is inside outer pair [i,l].
  // We scan to find such indices.

  // Collect all '[' indices
  const openIndices = [];
  for (let i = 0; i < n; i++) {
    if (s[i] === '[') openIndices.push(i);
  }
  // Collect all ']' indices
  const closeIndices = [];
  for (let i = 0; i < n; i++) {
    if (s[i] === ']') closeIndices.push(i);
  }

  // For each possible outer '[' index i
  // find inner '[' index j > i
  // then find inner ']' index k > j
  // then find outer ']' index l > k
  // If such quadruple exists, return true.

  // To speed up, we use binary search on sorted arrays openIndices and closeIndices.

  function upperBound(arr, x) {
    // returns smallest index in arr with arr[idx] > x, or arr.length if none
    let left = 0, right = arr.length;
    while (left < right) {
      let mid = (left + right) >> 1;
      if (arr[mid] > x) right = mid;
      else left = mid + 1;
    }
    return left;
  }

  for (let oi = 0; oi < openIndices.length; oi++) {
    let i = openIndices[oi];
    // find j > i
    let jpos = upperBound(openIndices, i);
    if (jpos === openIndices.length) continue;
    let j = openIndices[jpos];
    // find k > j
    let kpos = upperBound(closeIndices, j);
    if (kpos === closeIndices.length) continue;
    let k = closeIndices[kpos];
    // find l > k
    let lpos = upperBound(closeIndices, k);
    if (lpos === closeIndices.length) continue;
    let l = closeIndices[lpos];
    // found i<j<k<l with s[i]=='[' s[j]=='[' s[k]==']' s[l]==']'
    return true;
  }
  return false;
}

function solve(args) {
  const gpas = args[0];
  const thresholds = [
    [3.7, "A"],
    [3.3, "A-"],
    [3.0, "B+"],
    [2.7, "B"],
    [2.3, "B-"],
    [2.0, "C+"],
    [1.7, "C"],
    [1.3, "C-"],
    [1.0, "D+"],
    [0.7, "D"],
    [0.0, "D-"]
  ];
  const result = [];
  for (let i = 0; i < gpas.length; i++) {
    const g = gpas[i];
    if (g === 4) {
      result.push("A+");
    } else if (g === 0) {
      result.push("E");
    } else {
      let grade = "E";
      for (let j = 0; j < thresholds.length; j++) {
        if (g > thresholds[j][0]) {
          grade = thresholds[j][1];
          break;
        }
      }
      result.push(grade);
    }
  }
  return result;
}

function solve(args) {
  const gpas = args[0];
  const thresholds = [
    {limit: 3.7, grade: "A"},
    {limit: 3.3, grade: "A-"},
    {limit: 3.0, grade: "B+"},
    {limit: 2.7, grade: "B"},
    {limit: 2.3, grade: "B-"},
    {limit: 2.0, grade: "C+"},
    {limit: 1.7, grade: "C"},
    {limit: 1.3, grade: "C-"},
    {limit: 1.0, grade: "D+"},
    {limit: 0.7, grade: "D"},
    {limit: 0.0, grade: "D-"}
  ];
  const result = [];
  for (let gpa of gpas) {
    if (gpa === 4) {
      result.push("A+");
    } else if (gpa === 0) {
      result.push("E");
    } else {
      let assigned = false;
      for (let {limit, grade} of thresholds) {
        if (gpa > limit) {
          result.push(grade);
          assigned = true;
          break;
        }
      }
      if (!assigned) {
        // If no threshold strictly exceeded, gpa must be 0 < gpa <= 0.0, assign D- (lowest)
        result.push("D-");
      }
    }
  }
  return result;
}
